using System;using Mono.Cecil;class P{static int Main(){var a=AssemblyDefinition.ReadAssembly(@"F:\vam1.22.0.12\VaM_Data\Managed\Assembly-CSharp.dll");foreach(var tn in new[]{"SuperController","LookInputModule","SteamVR_ControllerManager","VRManager","VRInputModule"}){var t=a.MainModule.GetType(tn);if(t==null)continue;foreach(var f in t.Fields)if(f.Name.ToLower().Contains("pitch")||f.Name.ToLower().Contains("angle")||f.Name.ToLower().Contains("offset")||f.Name.ToLower().Contains("rotat"))Console.WriteLine(tn+" field "+f.FieldType.Name+" "+f.Name);foreach(var p in t.Properties)if(p.Name.ToLower().Contains("pitch")||p.Name.ToLower().Contains("angle")||p.Name.ToLower().Contains("offset"))Console.WriteLine(tn+" prop "+p.PropertyType.Name+" "+p.Name);}return 0;}}
